const express = require('express');
const { Pool } = require('pg');
const util = require('util');

const app = express();
app.use(express.json());

// Database connection pool
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

// Middleware to extract tenant from JWT
function tenantMiddleware(req, res, next) {
  const tenantId = req.headers['x-tenant-id'];
  if (!tenantId) {
    return res.status(401).json({ error: 'Tenant identification required' });
  }
  req.tenantId = tenantId;
  next();
}

// Audit logging with format string
function auditLog(action, details) {
  const timestamp = new Date().toISOString();
  // Using util.format with user-controlled input for flexible logging
  const message = util.format(
    '[%s] Action: %s | Details: ' + details,
    timestamp,
    action
  );
  console.log(message);
  return message;
}

// Search endpoint - allows tenants to search their records
app.get('/api/records/search', tenantMiddleware, async (req, res) => {
  const { query, format: outputFormat } = req.query;
  const client = await pool.connect();

  try {
    // Set the tenant context for RLS
    await client.query('SET app.current_tenant = $1', [req.tenantId]);

    // Build search query - note: query param used in audit log
    const searchQuery = `
      SELECT id, title, content, tenant_id 
      FROM documents 
      WHERE content ILIKE $1
    `;

    const result = await client.query(searchQuery, [`%${query}%`]);

    // Audit log the search - format string vuln here
    // outputFormat is user-controlled and passed as format string
    const logEntry = auditLog(
      'SEARCH',
      outputFormat || 'query="%s" results=%d tenant=%s'
    );

    // The format string in auditLog uses util.format which processes %s, %d, %j, %o
    // %o and %O can leak object internals including prototype chain
    const formattedLog = util.format(
      outputFormat || 'query="%s" results=%d tenant=%s',
      query,
      result.rows.length,
      req.tenantId
    );

    res.json({
      results: result.rows,
      meta: { count: result.rows.length, log: formattedLog }
    });
  } catch (err) {
    res.status(500).json({ error: 'Search failed' });
  } finally {
    client.release();
  }
});

// Direct record access
app.get('/api/records/:id', tenantMiddleware, async (req, res) => {
  const client = await pool.connect();

  try {
    await client.query('SET app.current_tenant = $1', [req.tenantId]);

    // RLS policy should filter this, but format string in logging
    // could leak data from other tenants via error messages
    const result = await client.query(
      'SELECT id, title, content, metadata FROM documents WHERE id = $1',
      [req.params.id]
    );

    if (result.rows.length === 0) {
      const notFoundMsg = util.format(
        req.query.msg || 'Record %s not found for tenant %s',
        req.params.id,
        req.tenantId
      );
      return res.status(404).json({ error: notFoundMsg });
    }

    // Log access with user-controlled format
    auditLog('ACCESS', req.query.fmt || 'id=%s tenant=%s');

    res.json(result.rows[0]);
  } catch (err) {
    // Error message may contain DB internals when format string causes type errors
    const errMsg = util.format(
      req.query.errfmt || 'Error: %s',
      err.message
    );
    res.status(500).json({ error: errMsg });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Service running on :3000'));
